    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) {
            return defaultValue;
        }
        if (Array.isArray(current)) {
            if (current.length > 0) {
                 const actualValue = current[0];
                 if (typeof actualValue === 'boolean') {
                     return actualValue;
                 }
                 return Array.isArray(actualValue) ? actualValue : String(actualValue);
            } else {
                return defaultValue;
            }
        }
        if (typeof current === 'boolean') {
            return current;
        }
        return String(current);
    }

    function updateProgressBar(barId, valueMainId, valueDescId, rawValueFromCharacterData, min, max, color) {
        const progressBar = document.getElementById(barId);
        const valueMainDisplay = document.getElementById(valueMainId);
        const valueDescDisplay = document.getElementById(valueDescId);
        if (!valueMainDisplay) {
            return;
        }
        let fullDisplayString = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
        let numericValue = min;
        let descriptionText = "";
        const descriptionMatch = String(fullDisplayString).match(/\((.+)\)$/);
        if (descriptionMatch && descriptionMatch[1]) {
            descriptionText = descriptionMatch[1];
            fullDisplayString = String(fullDisplayString).substring(0, descriptionMatch.index).trim();
        }
        const valueMatch = String(fullDisplayString).match(/(-?\d+(\.\d+)?)(?=[^\d.]*$|->)/);
         if (valueMatch) {
            numericValue = parseFloat(valueMatch[1]);
            const parts = String(fullDisplayString).split('->');
            valueMainDisplay.innerText = parts.length > 1 ? parts[1].trim() : parts[0].trim();
         } else if (!isNaN(parseFloat(fullDisplayString))) {
             numericValue = parseFloat(fullDisplayString);
             valueMainDisplay.innerText = fullDisplayString;
         } else {
             if (Array.isArray(rawValueFromCharacterData) && typeof rawValueFromCharacterData[0] === 'number') {
                 numericValue = rawValueFromCharacterData[0];
                 valueMainDisplay.innerText = String(numericValue);
             } else if (typeof rawValueFromCharacterData === 'number' || typeof rawValueFromCharacterData === 'string') {
                 valueMainDisplay.innerText = String(rawValueFromCharacterData);
             } else {
                 valueMainDisplay.innerText = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
             }
         }
        if (valueDescDisplay) {
            valueDescDisplay.innerText = descriptionText ? `(${descriptionText})` : "";
        }
        if (progressBar) {
            numericValue = Math.max(min, Math.min(max, numericValue));
            const range = max - min;
            const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
            progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
            if(color) {
                progressBar.style.backgroundColor = color;
            } else {
                progressBar.style.backgroundColor = 'var(--accent-highlight)';
            }
        }
    }

    function setWeatherEmoji(weatherText) {
        const weatherEl = document.getElementById('world-weather');
        if (!weatherEl) return;
        let emoji = '☀️';
        if (weatherText.includes('雨')) emoji = '🌧️';
        else if (weatherText.includes('雪')) emoji = '❄️';
        else if (weatherText.includes('曇') || weatherText.includes('云')) emoji = '☁️';
        weatherEl.innerText = `${emoji} ${weatherText}`;
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (messages empty)</p>";
                return;
            }
            const gameData = messages[0].data;
            const characterData = gameData.display_data || gameData.stat_data;
            if (!characterData) {
                 document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (characterData missing)</p>";
                 return;
            }

            const charKey = "敏子";
            const worldKey = "世界";

            if (characterData.hasOwnProperty(worldKey)) {
                document.getElementById('world-datetime').innerText = SafeGetValue(characterData, `${worldKey}.日期时间`, 'N/A');
                document.getElementById('world-location').innerText = SafeGetValue(characterData, `${worldKey}.地点`, 'N/A');
                const weather = SafeGetValue(characterData, `${worldKey}.天气`, '晴朗');
                setWeatherEmoji(weather);
            }

            if (characterData.hasOwnProperty(charKey)) {
                updateProgressBar('toshiko-affection-bar', 'toshiko-affection', null, SafeGetValue(characterData, `${charKey}.与<user>的好感度`), -100, 100, 'var(--accent-highlight)');
                document.getElementById('toshiko-inner-thought').innerText = SafeGetValue(characterData, `${charKey}.状态.内心想法`, '...');

                updateProgressBar('toshiko-ability-political-bar', 'toshiko-ability-political', null, SafeGetValue(characterData, `${charKey}.能力.政治`), 0, 100, 'var(--ability-political)');
                updateProgressBar('toshiko-ability-military-bar', 'toshiko-ability-military', null, SafeGetValue(characterData, `${charKey}.能力.军事`), 0, 100, 'var(--ability-military)');
                updateProgressBar('toshiko-ability-commercial-bar', 'toshiko-ability-commercial', null, SafeGetValue(characterData, `${charKey}.能力.商业`), 0, 100, 'var(--ability-commercial)');

                document.getElementById('toshiko-status-face').innerText = SafeGetValue(characterData, `${charKey}.状态.面部表情`, '...');
                document.getElementById('toshiko-status-lips').innerText = SafeGetValue(characterData, `${charKey}.状态.嘴唇`, '...');
                document.getElementById('toshiko-status-attire').innerText = SafeGetValue(characterData, `${charKey}.状态.穿着`, '...');
                document.getElementById('toshiko-status-feet').innerText = SafeGetValue(characterData, `${charKey}.状态.双足`, '...');
                document.getElementById('toshiko-status-breasts').innerText = SafeGetValue(characterData, `${charKey}.状态.乳房`, '...');
                document.getElementById('toshiko-status-private').innerText = SafeGetValue(characterData, `${charKey}.状态.私处`, '...');
                document.getElementById('toshiko-status-anus').innerText = SafeGetValue(characterData, `${charKey}.状态.菊穴`, '...');

                document.getElementById('toshiko-resource-money').innerText = SafeGetValue(characterData, `${charKey}.资源.金钱`, '...');
                document.getElementById('toshiko-resource-connections').innerText = SafeGetValue(characterData, `${charKey}.资源.人脉`, '...');
                const items = SafeGetValue(characterData, `${charKey}.资源.物品`, []);
                document.getElementById('toshiko-resource-items').innerText = Array.isArray(items) ? items.join(', ') : items;
            } else {
                 document.getElementById('toshiko-affection').innerText = 'N/A';
            }
        } catch (error) {
            document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        }
    }

    function toggleSection(element) {
        const content = element.nextElementSibling;
        const arrow = element.querySelector('.arrow');
        if (!content || !arrow) return;
        const isExpanded = content.classList.toggle('expanded');
        element.classList.toggle('expanded-header', isExpanded);
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
